// Gmail API returns base64url-encoded body and headers as [{name,value}] array
const item = $input.first().json;

// --- helpers ---
function decodeBase64url(str) {
  if (!str) return '';
  // Gmail uses base64url: replace - with + and _ with /
  const base64 = str.replace(/-/g, '+').replace(/_/g, '/');
  return Buffer.from(base64, 'base64').toString('utf-8');
}

function stripHtml(h) {
  return h
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s{3,}/g, '\n\n')
    .trim();
}

// Recursively walk payload.parts to find text/plain and text/html
function extractBody(payload) {
  if (!payload) return '';
  let textBody = '';
  let htmlBody = '';

  // Non-multipart: body is directly on payload
  if (payload.body && payload.body.data) {
    const decoded = decodeBase64url(payload.body.data);
    if (payload.mimeType === 'text/plain') textBody = decoded;
    else htmlBody = decoded;
  }

  function walkParts(parts) {
    if (!parts) return;
    for (const part of parts) {
      if (part.mimeType === 'text/plain' && part.body && part.body.data) {
        textBody = textBody || decodeBase64url(part.body.data);
      } else if (part.mimeType === 'text/html' && part.body && part.body.data) {
        htmlBody = htmlBody || decodeBase64url(part.body.data);
      }
      // Recurse into nested multipart
      if (part.parts) walkParts(part.parts);
    }
  }
  walkParts(payload.parts);

  return textBody || (htmlBody ? stripHtml(htmlBody) : '');
}

// Flatten Gmail headers array → plain object
const hdr = {};
(item.payload && item.payload.headers || []).forEach(h => {
  hdr[h.name.toLowerCase()] = h.value;
});

const subject = hdr['subject'] || '(no subject)';
const from    = hdr['from']    || '';
const date    = hdr['date']    || new Date().toISOString();
const body    = extractBody(item.payload) || item.snippet || '';

return [{
  json: {
    subject,
    from,
    body:       body.slice(0, 3000),
    receivedAt: date,
    messageId:  item.id || ''
  }
}];

