const item = $input.first().json;

// Claude returns { content: [{ type: 'text', text: '...' }] }
const raw = item?.content?.[0]?.text || item?.choices?.[0]?.message?.content || '';

let parsed = {};
try {
  // Strip any markdown fences Claude might add
  const clean = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  parsed = JSON.parse(clean);
} catch(e) {
  // Fallback: keep the raw text so we can debug
  return [{ json: {
    portal: 'altro',
    tipo: 'richiesta',
    nome_cliente: null,
    telefono: null,
    email_cliente: null,
    appartamento: null,
    messaggio: null,
    _parse_error: raw
  }}];
}

// Build the Trello checklist item label
const tipo_label = parsed.tipo === 'chiamata_persa' ? 'Chiamata Persa' : 'Richiesta';
const nome  = parsed.nome_cliente  || 'N/D';
const tel   = parsed.telefono      || 'N/D';
const appt  = parsed.appartamento  || 'N/D';
const msg   = parsed.messaggio     ? ` | "${parsed.messaggio.slice(0, 80)}"` : '';

const trello_item = `${nome} | Tel: ${tel} | ${appt} | ${tipo_label}${msg}`;

return [{ json: { ...parsed, trello_item } }];
